#!/usr/bin/env python3
"""
Run from your project root:
  python3 fix_engine.py

Writes a clean IssuanceEngine.tsx directly — no copy-paste.
"""
import base64, os, sys

TARGET = os.path.join(os.getcwd(), "components", "IssuanceEngine.tsx")

if not os.path.exists("components"):
    print("ERROR: Run from project root (the folder containing components/)")
    sys.exit(1)

CONTENT_B64 = """"""

content = base64.b64decode(CONTENT_B64).decode("utf-8")
lines   = content.splitlines()

print(f"Writing {len(lines)}-line clean IssuanceEngine.tsx to {TARGET}")

with open(TARGET, "w", encoding="utf-8", newline="\n") as f:
    f.write(content)

# Verify
check = open(TARGET, encoding="utf-8").read()
ok = (
    check.splitlines()[0] == '"use client";'
    and "import React," in check
    and "export default function IssuanceEngine" in check
    and check.count('"use client"') == 1
)
if ok:
    print("SUCCESS — file verified clean")
    print("Now run: npm run build")
else:
    print("WARNING — verification failed, check the file manually")
